<span class="line"><span style="--shiki-light:#FFC799;--shiki-dark:#FFC799;">  email</span><span style="--shiki-light:#FFF;--shiki-dark:#FFF;">: </span><span style="--shiki-light:#99FFE4;--shiki-dark:#99FFE4;">admin@example.com</span></span>
